from z3 import *

W = 5
G = 7
P_per_group = 3
N = 21

x = [[Int(f"x_{w}_{p}") for p in range(N)] for w in range(W)]
s = Solver()

for w in range(W):
    for p in range(N):
        s.add(x[w][p] >= 0, x[w][p] < G)

for w in range(W):
    for g in range(G):
        s.add(Sum([If(x[w][p] == g, 1, 0) for p in range(N)]) == P_per_group)

for p1 in range(N):
    for p2 in range(p1+1, N):
        s.add(Sum([If(x[w][p1] == x[w][p2], 1, 0) for w in range(W)]) <= 1)

# Symmetry breaking: fix week 0
for p in range(N):
    s.add(x[0][p] == p // 3)

print("Solving...")
result = s.check()
print(f"Result: {result}")

if result == sat:
    m = s.model()
    schedule = [[m[x[w][p]].as_long() for p in range(N)] for w in range(W)]

    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[schedule[w][p]].append(p)
        print(f"Week {w}: {groups}")

    ok = True
    for w in range(W):
        for g in range(G):
            cnt = sum(1 for p in range(N) if schedule[w][p] == g)
            if cnt != 3:
                print(f"ERROR: Week {w}, Group {g} has {cnt} players")
                ok = False

    for p1 in range(N):
        for p2 in range(p1+1, N):
            meetings = sum(1 for w in range(W) if schedule[w][p1] == schedule[w][p2])
            if meetings > 1:
                print(f"ERROR: Golfers {p1} and {p2} meet {meetings} times")
                ok = False

    if ok:
        print("All constraints satisfied!")

    flat = []
    for w in range(W):
        for p in range(N):
            flat.append(schedule[w][p])

    print(f"\nFlat list (length {len(flat)}):")
    print(flat)
